package com.emergency.patient.models;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * RetinaSegmentationResult — Encapsulates the inference outcome generated by the
 * NetraProof Retinal Lesion Segmentation pipeline.
 *
 * Model Specifications:
 *  - Architecture: U-Net + SE-ResNeXt50
 *  - Segmented Targets: 4 classes (Cotton Wool Spots, Hard Exudates, Hemorrhages, Microaneurysms)
 *
 * Clinical & Architectural Independence:
 *  - Operates as an independent computer vision pipeline.
 *  - Its segmented visual masks do not explain, validate, or substitute for the
 *    diabetic retinopathy severity grade produced by the separate EfficientNet-B0 ensemble model.
 */
public class RetinaSegmentationResult implements Serializable {

    public enum SegmentationState {
        INITIAL("Initial", "Ready to initialize lesion segmentation analysis."),
        IN_PROGRESS("Analyzing Lesions", "Running U-Net + SE-ResNeXt50 segmentation over retinal microvasculature..."),
        SUCCESS("Segmentation Complete", "All four retinal lesion masks successfully generated."),
        PARTIAL("Partial Segmentation", "Some lesion masks were generated while others were unavailable."),
        FAILED("Segmentation Failed", "Unable to complete lesion segmentation. Please check connection and retry."),
        SERVICE_UNAVAILABLE("Segmentation Service Pending", "The NetraProof U-Net + SE-ResNeXt50 segmentation service is pending remote server deployment.");

        private final String defaultTitle;
        private final String defaultDescription;

        SegmentationState(String defaultTitle, String defaultDescription) {
            this.defaultTitle = defaultTitle;
            this.defaultDescription = defaultDescription;
        }

        public String getDefaultTitle() {
            return defaultTitle;
        }

        public String getDefaultDescription() {
            return defaultDescription;
        }
    }

    private String sessionId;
    private String patientUuid;
    private String imagePath;
    private String fileName;
    private int imageWidth;
    private int imageHeight;
    private long fileSizeBytes;
    private DrSeverityGrade drSeverityGrade;

    private SegmentationState segmentationState = SegmentationState.INITIAL;
    private String modelName = "U-Net + SE-ResNeXt50";
    private String modelVersion = "NetraProof-UNet-SEResNeXt50-v1.0";
    private long inferenceTimestamp = 0;
    private long processingDurationMs = 0;
    private String failureReason = null;

    private final Map<LesionCategory, LesionMaskData> masks = new EnumMap<>(LesionCategory.class);

    public RetinaSegmentationResult() {
        for (LesionCategory cat : LesionCategory.values()) {
            masks.put(cat, new LesionMaskData(cat));
        }
    }

    public LesionMaskData getMask(LesionCategory category) {
        return masks.get(category);
    }

    public List<LesionMaskData> getAllMasks() {
        return new ArrayList<>(masks.values());
    }

    public boolean hasAnyVisibleMask() {
        for (LesionMaskData mask : masks.values()) {
            if (mask.isVisible() && mask.isAvailable()) {
                return true;
            }
        }
        return false;
    }

    public boolean hasAnyAvailableMask() {
        for (LesionMaskData mask : masks.values()) {
            if (mask.isAvailable()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Determines whether the downstream AI Screening Report can be generated.
     * Requires valid session reference and completed screening pipeline context.
     */
    public boolean isReportUnlocked() {
        // Can proceed if session and image are verified, and segmentation has been evaluated
        // (even if remote service is pending or returned partial results, an annotated partial report is generated)
        return sessionId != null && !sessionId.isEmpty() && imagePath != null && !imagePath.isEmpty();
    }

    // ─── Getters & Setters ────────────────────────────────────────────────────

    public String getSessionId() {
        return sessionId;
    }

    public void setSessionId(String sessionId) {
        this.sessionId = sessionId;
    }

    public String getPatientUuid() {
        return patientUuid;
    }

    public void setPatientUuid(String patientUuid) {
        this.patientUuid = patientUuid;
    }

    public String getImagePath() {
        return imagePath;
    }

    public void setImagePath(String imagePath) {
        this.imagePath = imagePath;
    }

    public String getFileName() {
        return fileName;
    }

    public void setFileName(String fileName) {
        this.fileName = fileName;
    }

    public int getImageWidth() {
        return imageWidth;
    }

    public void setImageWidth(int imageWidth) {
        this.imageWidth = imageWidth;
    }

    public int getImageHeight() {
        return imageHeight;
    }

    public void setImageHeight(int imageHeight) {
        this.imageHeight = imageHeight;
    }

    public long getFileSizeBytes() {
        return fileSizeBytes;
    }

    public void setFileSizeBytes(long fileSizeBytes) {
        this.fileSizeBytes = fileSizeBytes;
    }

    public DrSeverityGrade getDrSeverityGrade() {
        return drSeverityGrade;
    }

    public void setDrSeverityGrade(DrSeverityGrade drSeverityGrade) {
        this.drSeverityGrade = drSeverityGrade;
    }

    public SegmentationState getSegmentationState() {
        return segmentationState;
    }

    public void setSegmentationState(SegmentationState segmentationState) {
        this.segmentationState = segmentationState;
    }

    public String getModelName() {
        return modelName;
    }

    public void setModelName(String modelName) {
        this.modelName = modelName;
    }

    public String getModelVersion() {
        return modelVersion;
    }

    public void setModelVersion(String modelVersion) {
        this.modelVersion = modelVersion;
    }

    public long getInferenceTimestamp() {
        return inferenceTimestamp;
    }

    public void setInferenceTimestamp(long inferenceTimestamp) {
        this.inferenceTimestamp = inferenceTimestamp;
    }

    public long getProcessingDurationMs() {
        return processingDurationMs;
    }

    public void setProcessingDurationMs(long processingDurationMs) {
        this.processingDurationMs = processingDurationMs;
    }

    public String getFailureReason() {
        return failureReason;
    }

    public void setFailureReason(String failureReason) {
        this.failureReason = failureReason;
    }
}

